Lemma AMBraw_body : forall W m m' b es out insz outpos outend,
  AMBraw m b es out insz outpos outend -> munch W m m' -> wmono asegs m m' -> Forall awin W ->
  disjoint_from W b 24 -> (forall x s, In (x, s) es -> disjoint_from W x (mb_block_size s)) ->
  exists ls, dl_ok (b + 8) (map fst es) ls /\ ALSCells m' ls /\ AMBElems m' es /\ AMBShad m' es /\ accessible m' b 64.
Proof.
  intros W m m' b es out insz outpos outend (ls & H0 & H1 & DL & LC & EL & AOK & SH & AB) MU WM FA DB DE.
  exists ls. split; [exact DL|]. split.
  { eapply ALSCells_transport; [exact LC| exact MU| exact WM|]. intros a n La.
    destruct (mb_lnode_cases _ _ _ _ _ DL AOK La) as [->|(s & IN)].
    - eapply disjoint_from_sub; [exact DB| lia| lia].
    - destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _). eapply disjoint_from_sub; [exact (DE a s IN)| lia| lia]. }
  split.
  { eapply AMBElems_transport; [exact EL| exact MU| exact WM|].
    intros x s IN. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _). split; [lia|]. eapply disjoint_from_sub; [exact (DE x s IN)| lia| lia]. }
  split.
  { intros x s IN. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (P & _ & S0 & R1 & _ & R2 & R3 & R4 & _).
    eapply addressable_transport_awin'; [exact (SH x s IN)| exact MU| exact WM| exact FA| lia]. }
  eapply accessible_transport_awin; [exact AB| exact MU| exact FA].
Qed.

