  Local Ltac bchk B8 g :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
      lazymatch goal with MUx : munch _ _ mx, WMx : wmono _ _ mx |- _ =>
        let RD := fresh "RD" in
        destruct (AMBraw_body _ _ mx _ _ _ _ _ _ MID MUx WMx cm_FW cm_DB cm_DE) as (_ & _ & _ & _ & _ & ABx);
        pose proof (accessible_read0_sr mx b 64 g ABx ltac:(clear; lia) ltac:(clear - B8; Z.div_mod_to_equations; lia) ltac:(clear; lia)) as RD;
        clear ABx
      end end.
  Local Ltac echk IN xe se X16 XB g :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
      lazymatch goal with MUx : munch _ _ mx, WMx : wmono _ _ mx |- _ =>
        let RD := fresh "RD" in
        destruct (AMBraw_body _ _ mx _ _ _ _ _ _ MID MUx WMx cm_FW cm_DB cm_DE) as (_ & _ & _ & _ & SHx & _);
        pose proof (accessible_read0_sr mx xe (mb_block_size se) g
                      (addressable_accessible _ _ _ xe (mb_block_size se) (SHx xe se IN) ltac:(clear; lia) ltac:(clear; lia) ltac:(unfold AAPP_HI; clear - XB; lia))
                      ltac:(clear; lia) ltac:(clear - X16; Z.div_mod_to_equations; lia) ltac:(clear - XB; lia)) as RD;
        clear SHx
      end end.

  (* [comment removed for export] *)
  Definition cm_st (pc : Z) (rax t0 t1 t2 : word) (out nc : Z) (a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) : machine_state :=
    MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (Z_to_bv 64 (b + 24)) (Z_to_bv 64 b)
            (Z_to_bv 64 (b + 48)) (Z_to_bv 64 out) (Z_to_bv 64 (b + 32)) a3 a4 a5 a6 a7
            (Z_to_bv 64 nc) (Z_to_bv 64 2147450880) (Z_to_bv 64 (Z.shiftr (b + 24) 3 + 2147450880)) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
       F (Z_to_bv 64 pc) fc None m (seg_rom asegs).
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

  (* [comment removed for export] *)
  Lemma cm_tail : forall (m1 : mem) (j0 : list byte) (back out sz prv op oe ic nc : Z) (jd : list byte)
      (rax t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
    munch W m0 m1 -> wmono asegs m0 m1 -> mem_inv asegs m1 ->
    cm_frame m1 j0 back -> stk asegs m1 lo (bv_unsigned sp + -64) ->
    rw_cells asegs m1 (b + 24) [C8 (Z_to_bv 64 out); C8 (Z_to_bv 64 ic); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 op); C8 (Z_to_bv 64 oe)] ->
    In (out, sz) (mb_put_es es insz n x) ->
    rw_cells asegs m1 out [C8 (Z_to_bv 64 (b + 8)); C8 (Z_to_bv 64 prv)] ->
    rw_cells asegs m1 (out + 16) [C8 (Z_to_bv 64 sz); CB (Z.to_nat (mb_block_size sz - 24)) jd] ->
    0 <= op -> nc = oe - op -> 1 <= nc -> ic + nc = insz + n -> 0 <= ic -> oe <= sz -> sz < 2^62 ->
    mb_out b (mb_put_es es insz n x) (insz + n) = (if oe =? sz then b + 8 else out) ->
    mb_outpos (mb_put_es es insz n x) (insz + n) = (if oe =? sz then 0 else oe) ->
    evt asegs (commit_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc b es insz n x lo shi m0)
