Lemma commit_spec : asan_memset_stmt -> commit_stmt.
Proof.
  intros MEMSET. intros until m. intros MID OK N1 NB ST LO CEIL RA MI SPAL AC SK SHI BSV.
  pose proof (mb_ok_bounds _ _ OK) as [IB CB0].
  eapply (commit_body MEMSET ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc b es insz n x lo shi m); try fast_eassumption.
  - exact (mb_put_ok es insz n x OK N1 NB).
  - clear - IB NB. lia.
Qed.

